INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63708745', 63708745, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pengadaan konsultan Perorangan Poksi Penyediaan Lahan Wilayah I', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 95000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Orang Bulan', 'Konsultan Perorangan bertugas memberikan dukungan teknis operasional kepada Direktorat Penyediaan Lahan dalam pelaksanaan fungsi penyediaan lahan pada Wilayah I, meliputi: (1) fasilitasi koordinasi dan sinkronisasi dengan satker/OPD provinsi/kabupaten serta pihak terkait; (2) pengumpulan, verifikasi, dan konsolidasi data kesiapan lahan (AOI/CPCL, status dan penguasaan lahan, serta kelengkapan dokumen pendukung) sesuai ketentuan yang berlaku; (3) asistensi penyusunan dan penelaahan dokumen perencanaan/teknis yang terkait penyediaan lahan, termasuk identifikasi isu, kendala, dan kebutuhan tindak lanjut; (4) pemantauan perkembangan pelaksanaan di wilayah serta penyusunan rekapitulasi capaian dan laporan kemajuan secara berkala; dan (5) penyampaian rekomendasi teknis untuk percepatan penyiapan lahan, mitigasi risiko, serta peningkatan kualitas data dan akuntabilitas pelaporan.', 'Konsultan Perorangan melaksanakan dukungan teknis penyediaan lahan pada Wilayah I dengan spesifikasi pekerjaan sebagai berikut: 1. melakukan fasilitasi koordinasi dan sinkronisasi data/agenda penyediaan lahan dengan satker/OPD provinsi/kabupaten dan pemangku kepentingan terkait; 2. menghimpun, memverifikasi, dan mengkonsolidasikan data kesiapan lahan (AOI/CPCL, status lahan, kesesuaian administrasi, serta dokumen pendukung) sesuai format dan standar yang ditetapkan; 3. memberikan asistensi penyiapan serta penelaahan kelengkapan dokumen teknis/administratif penyediaan lahan dan menyusun daftar isu, kendala, serta kebutuhan tindak lanjut; 4. melaksanakan pemantauan perkembangan pelaksanaan di wilayah, termasuk rekapitulasi capaian fisik/administratif dan pemutakhiran basis data pelaporan; dan5 5. menyusun laporan kemajuan berkala serta rekomendasi tindak korektif/mitigasi risiko untuk memastikan ketepatan waktu, keterlacakan, dan akuntabilitas pelaksanaan penyediaan lahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1110566);
