INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63708995', 63708995, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'Pengadaan konsultan Perorangan Poksi Pendayagunaan Lahan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 95000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Orang Bulan', 'Konsultan Perorangan bertugas memberikan dukungan teknis kepada Direktorat dalam rangka pelaksanaan pendayagunaan lahan dan penguatan tahapan pasca cetak sawah, meliputi: (1) fasilitasi koordinasi dengan satker/OPD provinsi/kabupaten serta pemangku kepentingan terkait untuk memastikan kesinambungan pengelolaan dan pemanfaatan lahan hasil cetak sawah; (2) pengumpulan, verifikasi, dan konsolidasi data pasca konstruksi (status serah terima, kondisi lahan dan prasarana pendukung, kesiapan pengelolaan/operasi, serta data CPCL/kelembagaan); (3) asistensi penyusunan rencana tindak lanjut pendayagunaan lahan, termasuk identifikasi kebutuhan sarana produksi, pendampingan, dan dukungan operasional sesuai ketentuan; (4) pemantauan perkembangan pemanfaatan lahan (awal tanam/indeks pertanaman, kendala teknis, dan isu keberlanjutan) serta penyusunan rekapitulasi capaian secara berkala; dan (5) penyampaian rekomendasi teknis untuk percepatan pemanfaatan lahan, mitigasi risiko pasca konstruksi, dan peningkatan kualitas data serta akuntabilitas pelaporan program.', 'Konsultan Perorangan melaksanakan dukungan teknis pendayagunaan lahan/pasca cetak sawah dengan spesifikasi pekerjaan sebagai berikut: 1. melakukan fasilitasi koordinasi dan sinkronisasi pelaksanaan pasca konstruksi dengan satker/OPD provinsi/kabupaten serta pemangku kepentingan terkait; 2. menghimpun, memverifikasi, dan mengkonsolidasikan data pasca cetak sawah, meliputi status serah terima (BAST/PHO/FHO), kondisi lahan dan prasarana/irigasi pendukung, serta kesiapan pengelolaan dan kelembagaan penerima manfaat; 3. memberikan asistensi penyiapan dan penelaahan rencana tindak lanjut pendayagunaan lahan, termasuk kebutuhan operasional awal, dukungan sarana/prasarana pendukung, dan jadwal pemanfaatan lahan; 4. melaksanakan pemantauan perkembangan pemanfaatan lahan (awal tanam/indikasi pemanfaatan, kendala teknis, dan isu keberlanjutan) serta melakukan pemutakhiran rekapitulasi capaian secara berkala; dan 5. menyusun laporan kemajuan dan rekomendasi tindak korektif/mitigasi risiko untuk memastikan keberlanjutan pemanfaatan lahan, ketepatan sasaran, serta akuntabilitas pelaporan program.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1114768);
